mapper.select:
SELECT a.id,a.user_id AS userId,a.job_id AS jobId,a.status, DATE_FORMAT(a.apply_time, '%Y-%m-%d %H:%i:%s') AS applyTime, DATE_FORMAT(a.cancel_time, '%Y-%m-%d %H:%i:%s') AS cancelTime, u.username,u.nickname,u.email,u.phone, j.company_name AS companyName,j.job_title AS jobTitle,j.salary,j.city,j.address,j.experience,j.education FROM application a INNER JOIN user u ON a.user_id = u.id INNER JOIN job j ON a.job_id = j.id
AND a.user_id = #{userId}
AND a.status = #{status}
ORDER BY a.apply_time DESC
